import {projectNavigation} from './oncall-navigation.js';
import {escapeHtml as esc} from './message-format.js';
import {localAt,localInstant,resultValue} from './oncall-planning.js';
const key=()=>Array.from(crypto.getRandomValues(new Uint8Array(16)),b=>b.toString(16).padStart(2,'0')).join('');
const ms=n=>Number(BigInt(n)/1_000_000n),kind=x=>Object.keys(x)[0];
const time=n=>n?new Date(ms(n)).toLocaleString([], {dateStyle:'medium',timeStyle:'short'}):'—';
const state=i=>({open:'Needs acknowledgement',acknowledged:'In progress',resolved:'Resolved'})[kind(i.status)];
const stamp=x=>JSON.stringify(x,(_,v)=>typeof v==='bigint'?String(v):v);
const status='<p data-response-status role="status" aria-live="polite"></p>';
const heading=(title,detail,action='')=>`<div class="page-heading"><div><span class="eyebrow">INCIDENT RESPONSE</span><h2>${esc(title)}</h2><p class="lead">${esc(detail)}</p></div>${action}</div>`;
export function createOncallResponse({root,api,session,getMe}){
 let generation=0,timer,identity='',dirty=false,routeKey='';
 const token=()=>session.load(),identityNow=()=>JSON.stringify([getMe()?.id,getMe()?.role]);
 const active=g=>{if(g!==generation)return false;if(identity!==identityNow()||!['admin','agent'].includes(getMe()?.role)){clear();root.replaceChildren();return false;}return true;};
 function clear(){generation++;clearTimeout(timer);root.oninput=null;dirty=false;routeKey='';}
 function notice(message){const e=root.querySelector('[data-response-status]');if(e)e.textContent=message;}
 async function run(button,work,done){const g=generation;if(!active(g)||button.disabled)return;button.disabled=true;notice('Saving…');try{const value=resultValue(await work());if(active(g)){dirty=false;await done(value);}}catch(e){if(active(g))notice(e.message.replace('This plan changed','This record changed'));}finally{if(active(g)&&button.isConnected)button.disabled=false;}}
 async function show(w,mode){
  const nextRoute=String(w.project.id)+'/'+mode;
  const retained=dirty&&routeKey===nextRoute&&identity===identityNow()?Array.from(root.querySelectorAll('input[id],textarea[id],select[id]')).map(e=>[e.id,e.value]):[];
  const expanded=retained.length?Array.from(root.querySelectorAll('details')).map(e=>e.open):[];
  clear();identity=identityNow();routeKey=nextRoute;const g=generation;
  const [overview]=await api().oncallResponse(token(),w.project.id);if(!active(g))return;
  if(!overview){root.innerHTML=heading('Response unavailable','Check your Hub project access and refresh.');return;}
  const base=`#/oncall/${w.project.id}`;
  root.innerHTML=`<a class="back-link" href="${base}">← ${esc(w.project.name)} · Coverage</a>`;
  if(mode==='response-settings'){if(!overview.canManage){root.insertAdjacentHTML('beforeend',heading('Setup requires an administrator','Roles are managed in Hub.'));return;}settings(w,overview,base);return;}
  if(mode==='incident-new'){create(w,overview,base);return;}
  if(mode.startsWith('incident-')){
   const id=BigInt(mode.slice(9)),[view]=await api().oncallIncident(token(),id);if(!active(g))return;
   if(!view||view.incident.projectId!==w.project.id){root.insertAdjacentHTML('beforeend',heading('Incident unavailable','It may have expired or your project access changed.'));return;}
   detail(w,view,base);poll(w,mode,view,()=>api().oncallIncident(token(),id));
  }else{overviewView(w,overview,base);poll(w,mode,overview,()=>api().oncallResponse(token(),w.project.id));}
  for(const[id,value]of retained){const e=root.querySelector('#'+id);if(e)e.value=value;}
  root.querySelectorAll('details').forEach((e,i)=>{if(expanded[i]!==undefined)e.open=expanded[i];});
  dirty=retained.length>0;root.oninput=()=>{dirty=true;};
 }
 function poll(w,mode,old,load){const g=generation;timer=setTimeout(async()=>{
  if(!active(g))return;if(document.hidden){poll(w,mode,old,load);return;}
  try{const [fresh]=await load();if(!active(g))return;
   if(!fresh){root.innerHTML=heading('Response unavailable','Your project access changed or this record expired.');return;}
   if(stamp(fresh)!==stamp(old)){if(dirty||root.contains(document.activeElement)&&document.activeElement?.matches('input,textarea,select,button')){notice('There is an update. Your input is kept; refresh before submitting.');}else{await show(w,mode);return;}}
   poll(w,mode,old,load);
  }catch(e){if(active(g)){notice('Live check failed. Refresh to verify current response.');poll(w,mode,old,load);}}
 },10000);}
 function refresh(w,mode){const b=root.querySelector('[data-response-refresh]');if(b)b.onclick=()=>show(w,mode).catch(e=>notice(e.message));}
 function overviewView(w,o,base){
  const open=o.incidents.filter(i=>kind(i.status)==='open'),progress=o.incidents.filter(i=>kind(i.status)==='acknowledged'),resolved=o.incidents.filter(i=>kind(i.status)==='resolved');
  root.insertAdjacentHTML('beforeend',heading(w.project.name,'One owner, a visible next step and a record of what happened.',o.policy[0]?.enabled?`<a class="button primary" href="${base}/incident-new">Report an incident ＋</a>`:'')+`${projectNavigation(w,'incidents','<button class="sm" data-response-refresh>Refresh</button>')}${status}`);
  if(!o.policy.length){root.insertAdjacentHTML('beforeend',`<section class="card oc-empty"><h3>A clear response when something breaks.</h3><p>Use the published rotation, give each responder time to acknowledge, and choose a fallback for uncovered hours.</p>${o.canManage?`<a class="button primary" href="${base}/response-settings">Set up response →</a>`:'<p>A Desk administrator can enable response for this project.</p>'}</section>`);refresh(w,'incidents');return;}
  root.insertAdjacentHTML('beforeend',`${!o.policy[0].enabled?'<p class="warnbox">New incident creation is paused. Existing responses continue.</p>':''}${!o.deliveryReady?'<p class="warnbox">Hub delivery is not configured. Open response settings before relying on notifications.</p>':''}<div class="oc-summary"><section class="card ${open.length?'oc-attention':''}"><span class="eyebrow">NEEDS ACKNOWLEDGEMENT</span><strong>${open.length}</strong><span>Someone must accept responsibility</span></section><section class="card"><span class="eyebrow">IN PROGRESS</span><strong>${progress.length}</strong><span>Explicitly owned response</span></section><section class="card"><span class="eyebrow">RESOLVED</span><strong>${resolved.length}</strong><span>Within this project's retained history</span></section></div><p class="oc-footnote">Hub acceptance is not a device-delivery receipt. No SMS or phone paging is configured by this module.</p><div class="btnrow oc-incident-filter" aria-label="Incident list"><button data-incident-filter="active">Active · ${open.length+progress.length}</button><button data-incident-filter="resolved">Resolved · ${resolved.length}</button><button data-incident-filter="all">All · ${o.incidents.length}</button></div><p data-incident-empty class="oc-footnote" hidden>No incidents in this view.</p><div class="oc-incident-list">${[...open,...progress,...resolved].map(i=>`<a class="card oc-incident-row" data-incident-state="${kind(i.status)}" href="${base}/incident-${i.id}"><div><span class="eyebrow">OC-${i.id} · ${esc(i.service)}</span><h3>${esc(i.title)}</h3><p>${esc(i.ownerName||'No one has acknowledged yet')} · ${esc(time(i.openedAt))}</p>${i.routeIssue?`<p class="oc-response-alert">${esc(i.routeIssue)}</p>`:''}</div><div><span class="oc-severity ${kind(i.severity)}">${esc(kind(i.severity))}</span><span class="rowsub">${state(i)}</span></div></a>`).join('')||'<section class="card oc-empty"><h3>No incidents recorded.</h3><p>When something breaks, report it here to start the response.</p></section>'}</div>`);refresh(w,'incidents');
  const filter=mode=>{let visible=0;root.querySelectorAll('[data-incident-state]').forEach(row=>{row.hidden=mode==='active'?row.dataset.incidentState==='resolved':mode==='resolved'?row.dataset.incidentState!=='resolved':false;if(!row.hidden)visible++;});root.querySelector('[data-incident-empty]').hidden=visible>0||o.incidents.length===0;root.querySelectorAll('[data-incident-filter]').forEach(b=>{const selected=b.dataset.incidentFilter===mode;b.classList.toggle('primary',selected);b.setAttribute('aria-pressed',String(selected));});};
  root.querySelectorAll('[data-incident-filter]').forEach(b=>b.onclick=()=>filter(b.dataset.incidentFilter));filter('active');
 }
 function settings(w,o,base){const p=o.policy[0],id=()=>root.querySelector('#rFallback').value;
  root.insertAdjacentHTML('beforeend',heading('Incident response','Published layers first. An explicit fallback if nobody takes over.')+projectNavigation(w,'response-settings')+`<form id="responseSettings" class="card oc-form"><label for="rEnabled">Incident response</label><select id="rEnabled"><option value="yes" ${p?.enabled?'selected':''}>Enabled</option><option value="no" ${p&&!p.enabled?'selected':''}>Pause new incidents</option></select><div class="row"><div><label for="rMinutes">Time to acknowledge · minutes</label><input type="number" id="rMinutes" min="1" max="60" value="${p?.ackMinutes||5}" required></div><div><label for="rFallback">Fallback responder</label><select id="rFallback" required><option value="">Choose a person</option>${w.members.map(m=>`<option value="${esc(m.id)}" ${p?.fallback===m.id?'selected':''}>${esc(m.name)}</option>`).join('')}</select></div></div><div class="oc-response-explainer"><strong id="rExplanation"></strong><p>If a layer has no eligible responder, Desk moves on at the next check. Acknowledgement stops further escalation. Shift changes do not transfer an owned incident.</p></div><details><summary>Retention & delivery limits</summary><label for="rRetention">Delete resolved incidents after · days</label><input type="number" id="rRetention" min="30" max="365" value="${p?.retentionDays||90}" required><p class="kv">Each new incident keeps this policy. Deletion includes notes, delivery records and unreviewed work entries. Unresolved incidents expire after 365 days. Historical backups and already delivered notifications need separate retention.</p><p class="kv">Desk stores pending notifications and retries up to three times. Hub controls bell/chat delivery preferences. A Hub receipt does not confirm device delivery. Test the complete notification path before operational use.</p></details><div class="btnrow"><button class="primary" type="submit">Save response settings</button><a class="button" href="${base}/incidents">Cancel</a></div>${status}</form>`);
  const explain=()=>{const name=w.members.find(m=>m.id===id())?.name||'the fallback';root.querySelector('#rExplanation').textContent=`Notify the current primary → wait ${root.querySelector('#rMinutes').value} min → next published layer → ${name}.`;};root.querySelector('#rMinutes').oninput=explain;root.querySelector('#rFallback').onchange=explain;explain();
  root.querySelector('form').onsubmit=e=>{e.preventDefault();run(e.submitter,()=>api().setOncallResponse(token(),w.project.id,p?.revision||0n,{enabled:root.querySelector('#rEnabled').value==='yes',ackMinutes:BigInt(root.querySelector('#rMinutes').value),fallback:id(),retentionDays:BigInt(root.querySelector('#rRetention').value)}),()=>{location.hash=base+'/incidents';});};
 }
 function create(w,o,base){const requestKey=key();
  root.insertAdjacentHTML('beforeend',heading('Report an incident','Report the impact. Desk finds the current responder.')+projectNavigation(w,'incidents')+`<form class="card oc-form"><label for="rService">Affected service</label><select id="rService">${w.project.services.map(s=>`<option>${esc(s)}</option>`).join('')}</select><label for="rTitle">What is happening?</label><input type="text" id="rTitle" required minlength="3" maxlength="160" placeholder="e.g. Customers cannot sign in"><label for="rSeverity">Impact</label><select id="rSeverity"><option value="major">Major · a service is impaired</option><option value="critical">Critical · widespread service loss</option><option value="minor">Minor · limited impact</option></select><label for="rDetail">What do we know so far?</label><textarea id="rDetail" maxlength="2000" placeholder="Symptoms, first checks and relevant context. Keep credentials and customer details out."></textarea><p class="kv">Submitting starts real Hub notifications in this environment. All impact levels currently use the project's response timing.</p><div class="btnrow"><button class="primary" type="submit" ${!o.policy[0]?.enabled?'disabled':''}>Start response</button><a class="button" href="${base}/incidents">Cancel</a></div>${status}</form>`);
  root.querySelector('form').onsubmit=e=>{e.preventDefault();run(e.submitter,()=>api().openOncallIncident(token(),requestKey,{projectId:w.project.id,service:root.querySelector('#rService').value,title:root.querySelector('#rTitle').value.trim(),severity:{[root.querySelector('#rSeverity').value]:null},detail:root.querySelector('#rDetail').value.trim()}),r=>{location.hash=base+'/incident-'+r.id;});};
 }
 function detail(w,v,base){const i=v.incident,s=kind(i.status),me=getMe(),own=i.owner===me.id,manage=own||me.role==='admin',h=v.handoff[0],pending=h&&kind(h.status)==='pending',reload=()=>show(w,'incident-'+i.id),zone=Intl.DateTimeFormat().resolvedOptions().timeZone,deliveryAttention=v.deliveries.some(d=>['pending','failed'].includes(kind(d.status))),deliveryLabel=v.deliveries.some(d=>kind(d.status)==='failed')?'Needs attention':v.deliveries.some(d=>kind(d.status)==='pending')?'Pending':v.deliveries.some(d=>kind(d.status)==='accepted')?'Hub accepted':'No pending delivery';
  root.insertAdjacentHTML('beforeend',heading(i.title,`OC-${i.id} · ${i.service} · ${state(i)}`,`<button data-response-refresh>Refresh</button>`)+`${projectNavigation(w,'incidents')}<div class="oc-incident-meta"><a href="${base}/incidents">← All incidents</a><span class="oc-severity ${kind(i.severity)}">${esc(kind(i.severity))}</span><span>Opened ${esc(time(i.openedAt))}</span></div><section class="card oc-response-next"><div><span class="eyebrow">${s==='open'?'NEXT ACTION':s==='resolved'?'OUTCOME':'RESPONSE OWNER'}</span><h3>${s==='open'?'Someone needs to take this.':s==='resolved'?'Resolved by the response team':esc(i.ownerName)}</h3><p>${s==='open'?(i.nextEscalation?`Next escalation check after ${esc(time(i.nextEscalation))}.`:'Manual response is required.'):(s==='resolved'?esc(i.resolution):'Ownership stays with this person until an accepted handoff.')}</p>${i.owner&&!w.members.some(m=>m.id===i.owner)?'<p class="oc-response-alert">This owner is no longer eligible. Desk will reopen response at its next directory-aware check.</p>':''}${i.routeIssue?`<p class="oc-response-alert">${esc(i.routeIssue)}</p>`:''}</div>${s==='open'?'<button id="rAck" class="primary">I’m on it</button>':s==='acknowledged'&&manage?`<div class="btnrow">${!pending?'<button data-open-handoff>Hand off…</button>':''}<button class="primary" data-open-resolve>Resolve…</button></div>`:''}</section>${status}${pending?`<section class="card oc-swap"><div><strong>Handoff requested · ${esc(h.toName)}</strong><p>${esc(h.summary)}</p><span class="kv">${esc(i.ownerName)} remains responsible until acceptance.</span></div><div class="btnrow">${h.to===me.id?'<button class="primary" data-handoff="accept">Accept responsibility</button><button data-handoff="decline">Decline</button>':''}${manage?'<button data-handoff="cancel">Cancel handoff</button>':''}</div></section>`:''}<div class="oc-response-layout"><section><div class="card"><h3>Response timeline</h3><ol class="oc-response-timeline">${v.events.map(e=>`<li><div><strong>${esc(e.name)}</strong><time>${esc(time(e.at))}</time></div><span class="eyebrow">${esc(e.kind.replaceAll('_',' '))}</span><p>${esc(e.text)}</p></li>`).join('')}</ol><form id="rNoteForm"><label for="rNote">Add an internal update</label><textarea id="rNote" required maxlength="2000" placeholder="What changed? What happens next?"></textarea><button type="submit">Add update</button></form></div>${s==='acknowledged'&&manage?`<section class="oc-response-decisions">${!pending?`<details class="card" id="rHandoffPanel"><summary>Hand off responsibility</summary><form id="rHandoffForm"><label for="rTo">Transfer responsibility to</label><select id="rTo" required><option value="">Choose a responder</option>${w.members.filter(m=>m.id!==i.owner).map(m=>`<option value="${esc(m.id)}">${esc(m.name)}</option>`).join('')}</select><label for="rSummary">Current state & next steps</label><textarea id="rSummary" maxlength="2000" required></textarea><button type="submit">Request handoff</button></form></details>`:''}<details class="card" id="rResolvePanel"><summary>Resolve incident</summary><form id="rResolveForm"><label for="rResolution">Verified outcome</label><textarea id="rResolution" minlength="3" maxlength="2000" required placeholder="What was checked and how was service restored?"></textarea><button class="primary" type="submit">Resolve incident</button></form></details></section>`:''}</section><aside>${v.monitoring?.[0]?`<section class="card oc-monitoring"><span class="eyebrow">MONITORING SIGNAL</span><h3>${v.monitoring[0].condition==='recovered'?'Recovery reported':'Alert firing'}</h3><p>${esc(v.monitoring[0].sourceName)}</p><span class="kv">Observed ${esc(time(v.monitoring[0].occurredAt))}<br>Received ${esc(time(v.monitoring[0].receivedAt))}</span><p class="kv">${v.monitoring[0].condition==='recovered'?'Verify recovery before closing. Ownership and escalation continue.':'This is the latest source report, not a live health check.'}</p></section>`:''}<section class="card"><h3>Service communication</h3><p class="kv">Publish a separate update for your audience. Incident notes remain private.</p><a class="button" href="${base}/status-new-${i.id}">Prepare status update</a></section><details class="card" ${deliveryAttention?'open':''}><summary>Notifications · ${deliveryLabel}</summary><p class="kv">Hub accepted ≠ delivered to a device ≠ acknowledged by a person.</p>${v.deliveries.map(d=>`<div class="oc-delivery"><strong>${esc(d.name)}</strong><span>${esc(kind(d.purpose))} · ${esc(kind(d.status)==='accepted'?'Hub accepted':kind(d.status)==='failed'?'Not confirmed':kind(d.status))}</span><p>${esc(d.detail)} · ${d.attempts} attempt${d.attempts===1n?'':'s'}</p></div>`).join('')||'<p class="kv">No eligible notification target yet.</p>'}</details><details class="card"><summary>Actual work · ${v.work.filter(x=>!x.voidedAt).length} entries</summary><p class="kv">Self-reported, not approved for payroll. Incident duration is not worked time. Entries are deleted with the incident.</p>${v.work.map(x=>`<div class="oc-delivery"><strong>${esc(x.name)} · ${x.voidedAt?'Voided':((ms(x.endAt)-ms(x.startAt))/60000-Number(x.breakMinutes)).toFixed(0)+' min'}</strong><span>${esc(time(x.startAt))} – ${esc(time(x.endAt))}</span><p>${esc(x.note)}${x.voidedAt?'<br>Correction: '+esc(x.voidReason):''}</p>${!x.voidedAt&&x.personId===me.id?`<button class="sm" data-void="${x.id}">Correct entry</button>`:''}</div>`).join('')}<div id="rCorrection"></div><form id="rWorkForm"><label for="rWorkStart">Started · ${esc(zone)}</label><input type="datetime-local" id="rWorkStart" required value="${localAt(Math.max(Math.ceil(ms(i.openedAt)/60000)*60000,Date.now()-15*60000),zone)}"><label for="rWorkEnd">Finished</label><input type="datetime-local" id="rWorkEnd" required value="${localAt(Date.now(),zone)}"><label for="rBreak">Breaks · minutes</label><input type="number" id="rBreak" min="0" value="0" required><label for="rWorkNote">Work performed</label><input type="text" id="rWorkNote" required maxlength="500"><button type="submit">Record my work</button></form></details></aside></div>`);
  refresh(w,'incident-'+i.id);
  for(const [action,panel,input] of [['handoff','rHandoffPanel','rTo'],['resolve','rResolvePanel','rResolution']])root.querySelector('[data-open-'+action+']')?.addEventListener('click',()=>{const box=root.querySelector('#'+panel);box.open=true;box.scrollIntoView?.({block:'center'});root.querySelector('#'+input).focus();});
  root.querySelector('#rAck')?.addEventListener('click',e=>run(e.currentTarget,()=>api().acknowledgeOncallIncident(token(),i.id,i.revision),reload));
  root.querySelectorAll('[data-handoff]').forEach(b=>b.onclick=()=>run(b,()=>api().decideOncallHandoff(token(),i.id,i.revision,{[b.dataset.handoff]:null}),reload));
  root.querySelector('#rNoteForm').onsubmit=e=>{e.preventDefault();run(e.submitter,()=>api().noteOncallIncident(token(),i.id,i.revision,root.querySelector('#rNote').value.trim()),reload);};
  const transfer=root.querySelector('#rHandoffForm');if(transfer)transfer.onsubmit=e=>{e.preventDefault();run(e.submitter,()=>api().handoffOncallIncident(token(),i.id,i.revision,root.querySelector('#rTo').value,root.querySelector('#rSummary').value.trim()),reload);};
  const resolve=root.querySelector('#rResolveForm');if(resolve)resolve.onsubmit=e=>{e.preventDefault();run(e.submitter,()=>api().resolveOncallIncident(token(),i.id,i.revision,root.querySelector('#rResolution').value.trim()),reload);};
  const workKey=key();root.querySelector('#rWorkForm').onsubmit=e=>{e.preventDefault();try{const input={startAt:localInstant(root.querySelector('#rWorkStart').value,zone),endAt:localInstant(root.querySelector('#rWorkEnd').value,zone),breakMinutes:BigInt(root.querySelector('#rBreak').value),note:root.querySelector('#rWorkNote').value.trim()};run(e.submitter,()=>api().recordOncallWork(token(),i.id,workKey,input),reload);}catch(e){notice(e.message);}};
  root.querySelectorAll('[data-void]').forEach(b=>b.onclick=()=>{dirty=true;const box=root.querySelector('#rCorrection');box.innerHTML='<form><label for="rCorrectionReason">Why is this entry incorrect?</label><input type="text" id="rCorrectionReason" required maxlength="500"><button type="submit">Void entry</button><p class="kv">The original stays in history. Add a corrected entry afterwards.</p></form>';box.querySelector('form').onsubmit=e=>{e.preventDefault();run(e.submitter,()=>api().voidOncallWork(token(),BigInt(b.dataset.void),box.querySelector('input').value.trim()),reload);};});
 }
 return{show,clear};
}
